250	.hero h1 .lab-green { color: #28c477; }
251	.hero h1 .lab-blue { color: #5b91ff; }
252	.hero-art { position: relative; width: min(42vw, 520px); aspect-ratio: auto; justify-self: end; border-radius: 0; background: none; }
253	.hero-art::before, .hero-art::after { display: none; }
254	.hero-logo-panel { position: static; width: 100%; padding: 12px; border: 1px solid rgba(255,255,255,.18); border-radius: 3px; background: #fff; box-shadow: 0 20px 55px rgba(0,0,0,.24); transform: none; }
255	.hero-logo-panel img { width: 100%; height: auto; display: block; }
