@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@300;400;500;600;700;800&family=Roboto:wght@300;400;500;600;700;800&display=swap");

:root {
  color-scheme: dark;
  --ink: #e8ece8;
  --muted: #a4afaa;
  --paper: #101714;
  --white: #19221e;
  --line: #35413b;
  --accent: #d98b65;
  --deep: #19372e;
  --serif: "Roboto", "Noto Sans KR", "Apple SD Gothic Neo", sans-serif;
  font-family: "Roboto", "Noto Sans KR", "Apple SD Gothic Neo", sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; color: var(--ink); background: var(--paper); line-height: 1.65; word-break: keep-all; overflow-wrap: anywhere; }
a { color: inherit; text-decoration: none; }
a:hover { color: var(--accent); }
button { font: inherit; }
img, svg { max-width: 100%; }
main, section, article, footer, nav, .section-wrap, .hero-copy { min-width: 0; }
.skip-link { position: absolute; top: -60px; left: 16px; z-index: 20; padding: 10px 14px; color: #fff; background: var(--ink); }
.skip-link:focus { top: 12px; }
.site-header { height: 88px; padding: 0 6.5vw; display: flex; align-items: center; justify-content: space-between; background: var(--paper); border-bottom: 1px solid var(--line); }
.brand { display: inline-flex; align-items: center; gap: 12px; line-height: 1.15; }
.brand-mark { width: 43px; height: 43px; display: block; flex: 0 0 auto; border-radius: 50%; color: transparent; background: #fff url("assets/knu-seal.png") center / cover no-repeat; font-size: 0; }
.brand-name { font-family: var(--serif); font-size: 14px; font-weight: 700; letter-spacing: .01em; }
.site-nav { display: flex; gap: clamp(12px, 1.7vw, 24px); align-items: center; }
.site-nav a { position: relative; font-size: 11px; font-weight: 650; letter-spacing: .015em; white-space: nowrap; }
.site-nav a[aria-current="page"]::after { position: absolute; right: 0; bottom: -8px; left: 0; height: 2px; background: var(--accent); content: ""; }
.menu-toggle { display: none; }
.hero { position: relative; min-height: 630px; padding: 86px 10vw 76px; overflow: hidden; display: grid; grid-template-columns: 1.05fr .95fr; align-items: center; background: #151f1b; }
.hero-copy { z-index: 1; max-width: 650px; }
.eyebrow { margin: 0 0 18px; color: var(--accent); font-size: 10px; font-weight: 750; letter-spacing: .18em; }
.hero h1 { margin: 0; font: 500 clamp(62px, 8.5vw, 116px)/.93 var(--serif); letter-spacing: -.065em; }
.hero h1 span { color: var(--accent); }
.hero-lead { max-width: 490px; margin: 28px 0 10px; font-size: 18px; font-weight: 650; line-height: 1.65; }
.hero-note { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.8; }
.button-row { display: flex; gap: 22px; align-items: center; flex-wrap: wrap; margin-top: 30px; }
.button { min-height: 48px; padding: 12px 19px; display: inline-flex; align-items: center; gap: 20px; font-size: 12px; font-weight: 700; }
.button-dark { color: #fff; background: var(--deep); }
.button-dark:hover { color: #fff; background: var(--accent); }
.button-light { color: #17201c; background: #f0eee7; }
.button-light:hover { color: #17201c; background: #fff; }
.button-outline { border: 1px solid var(--ink); }
.button-ghost-light { color: #fff; border: 1px solid rgba(255,255,255,.55); }
.text-link, .arrow-link { display: inline-flex; align-items: center; gap: 13px; font-size: 12px; font-weight: 700; }
.hero-art { position: relative; width: min(37vw, 450px); aspect-ratio: 1; justify-self: end; border-radius: 50%; background: radial-gradient(circle at 54% 46%, #e1aa7d 0 9%, #ac6045 10% 18%, #714533 19% 22%, transparent 23%), radial-gradient(circle, #352c25 0 30%, #8d503c 31% 32%, transparent 33%); }
.hero-art::before, .hero-art::after { position: absolute; inset: 12%; border: 1px solid rgba(218,178,142,.25); border-radius: 50%; content: ""; transform: rotate(-24deg) scaleY(.65); }
.hero-art::after { inset: 4%; transform: rotate(38deg) scaleY(.42); }
.orbit { position: absolute; z-index: 1; border: 1px solid rgba(218,178,142,.3); border-radius: 50%; }
.orbit-one { inset: 22% 4%; transform: rotate(57deg); }
.orbit-two { inset: 5% 25%; transform: rotate(-32deg); }
.heat-core { position: absolute; z-index: 2; top: 41%; left: 43%; width: 72px; height: 72px; display: grid; place-items: center; border-radius: 50%; color: #fff; background: var(--deep); font: 15px var(--serif); letter-spacing: .12em; box-shadow: 0 0 45px rgba(189,99,61,.38); }
.hero-logo-panel { position: absolute; z-index: 4; right: 2%; bottom: 8%; width: min(360px, 88%); padding: 5px; background: #fff; box-shadow: 0 18px 55px rgba(0,0,0,.32); transform: rotate(-3deg); }
.hero-logo-panel img { width: 100%; height: auto; display: block; }
.art-label { display: none; }
.hero-index { position: absolute; right: 6.5vw; bottom: 30px; left: 6.5vw; display: flex; justify-content: space-between; color: #a4afaa; font-size: 9px; letter-spacing: .14em; }
.hero-index span:first-child { color: var(--accent); font-family: var(--serif); font-size: 14px; }
.section-wrap { width: min(1200px, 88vw); margin: 0 auto; }
.intro { padding: 116px 0; display: grid; grid-template-columns: minmax(0, .65fr) minmax(0, 1.35fr); gap: 6vw; }
.section-kicker { display: flex; gap: 16px; color: var(--accent); font-size: 9px; font-weight: 750; letter-spacing: .15em; }
.section-kicker span:first-child { font-family: var(--serif); font-size: 17px; }
.intro h2, .section-heading h2, .profile-copy h2, .contact-primary h2 { margin: 0; font: 500 clamp(33px, 4vw, 51px)/1.17 var(--serif); letter-spacing: -.045em; }
.intro p:not(.eyebrow) { max-width: 670px; margin: 24px 0; color: var(--muted); font-size: 15px; }
.research-preview { padding: 28px 0 120px; }
.section-heading { display: flex; justify-content: space-between; align-items: end; gap: 24px; margin-bottom: 34px; }
.section-heading .eyebrow { margin-bottom: 8px; }
.research-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.research-card { position: relative; min-height: 265px; padding: 26px; display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; color: #fff; background: var(--deep); }
.research-card:nth-child(2) { background: #a45b3e; }
.research-card:nth-child(3) { color: var(--ink); background: #293630; }
.research-card::after { position: absolute; right: -44px; bottom: -74px; width: 180px; height: 180px; border: 1px solid currentColor; border-radius: 50%; opacity: .2; content: ""; }
.research-card:hover { color: #fff; background: var(--accent); }
.card-no { font-size: 9px; letter-spacing: .14em; opacity: .75; }
.research-card h3 { margin: 0; font: 500 clamp(23px, 2.6vw, 34px)/1.25 var(--serif); }
.card-arrow { align-self: flex-end; font-size: 19px; }
.news-band { padding: 94px 0 106px; background: #151f1b; }
.news-feature { padding: 20px 0; display: grid; grid-template-columns: 130px 1fr 30px; gap: 22px; align-items: center; border-top: 1px solid var(--line); }
.news-feature:last-child { border-bottom: 1px solid var(--line); }
.news-date { color: var(--accent); font-size: 10px; font-weight: 750; letter-spacing: .1em; }
.news-title { font-size: 14px; font-weight: 650; }
.news-arrow { justify-self: end; }
.publication-preview { padding: 100px 0 115px; }
.original-mission { padding: 10px 0 110px; display: grid; grid-template-columns: .65fr 1.35fr; gap: 6vw; }
.original-mission h2 { max-width: 760px; margin: 0; font: 500 clamp(31px, 4vw, 48px)/1.2 var(--serif); letter-spacing: -.035em; }
.legacy-topics { margin-top: 25px; display: flex; flex-wrap: wrap; gap: 9px; }
.legacy-topics span { padding: 8px 11px; border: 1px solid var(--line); color: var(--muted); font-size: 10px; }
.publication-item { padding: 22px 0; display: grid; grid-template-columns: 80px minmax(0, 1fr) 24px; gap: 22px; border-top: 1px solid var(--line); align-items: start; }
.publication-item:last-child { border-bottom: 1px solid var(--line); }
.publication-year { color: var(--accent); font: 17px var(--serif); }
.publication-item p { margin: 0; font-size: 13px; }
.publication-item em { color: var(--muted); font-size: 12px; }
.join-band { padding: 76px 0; color: #fff; background: var(--deep); }
.join-inner h2 { margin: 0; font: 500 clamp(34px, 5vw, 58px)/1.16 var(--serif); letter-spacing: -.045em; }
.join-inner > p:not(.eyebrow) { color: #c3cec8; font-size: 13px; }
.join-inner .button-row { margin-top: 25px; }
.site-footer { padding: 36px 6.5vw; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr) minmax(0, 1fr) auto; gap: 28px; align-items: center; background: #151f1b; font-size: 10px; color: var(--muted); }
.site-footer p { margin: 0; }
.brand-footer { color: var(--ink); }
.brand-footer .brand-mark { color: transparent; }
.copyright { font-size: 9px; }

.page-hero { padding: 88px 10vw 82px; background: #151f1b; }
.page-hero h1 { margin: 0; font: 500 clamp(52px, 7vw, 88px)/1.05 var(--serif); letter-spacing: -.06em; }
.page-hero > p:last-child { margin: 20px 0 0; color: var(--muted); font-size: 15px; }
.about-intro { padding: 100px 0 120px; display: grid; grid-template-columns: .65fr 1.35fr; gap: 6vw; }
.about-intro h2 { margin: 0 0 26px; font: 500 clamp(34px, 4vw, 52px)/1.18 var(--serif); letter-spacing: -.04em; }
.about-intro div > p:not(.eyebrow) { max-width: 720px; color: var(--muted); font-size: 15px; }
.about-intro .arrow-link { margin-top: 14px; }
.profile-section { padding: 94px 0 110px; background: #151f1b; }
.profile-layout { display: grid; grid-template-columns: .55fr 1.45fr; gap: 7vw; }
.profile-monogram { margin: 38px 0 0; color: #32423b; font: 500 clamp(50px, 8vw, 100px)/1 var(--serif); letter-spacing: -.08em; }
.profile-photo { width: min(100%, 290px); max-height: 390px; margin-top: 25px; display: block; object-fit: cover; object-position: center 20%; }
.profile-role { color: var(--muted); font-size: 13px; }
.profile-copy .text-link { margin: 10px 0 30px; }
.profile-facts { margin-top: 22px; display: grid; grid-template-columns: 1fr 1.3fr; gap: 24px; }
.profile-facts > div:last-child { grid-column: 1 / -1; }
.profile-facts h3 { margin: 0 0 8px; color: var(--accent); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; }
.profile-facts ul { margin: 0; padding-left: 17px; color: var(--muted); font-size: 12px; }
.inline-cta { padding: 88px 0; }
.inline-cta h2 { margin: 0; font: 500 clamp(32px, 4vw, 48px)/1.2 var(--serif); }
.research-detail-list { padding: 80px 0 120px; }
.research-intro { max-width: 700px; margin: 0 0 52px; color: var(--muted); font-size: 17px; }
.research-detail { padding: 38px 0 64px; display: grid; grid-template-columns: minmax(72px, .35fr) minmax(0, 1.65fr); gap: 5vw; border-top: 1px solid var(--line); scroll-margin-top: 24px; }
.research-number { color: var(--accent); font: 28px var(--serif); }
.research-detail h2 { margin: 0 0 18px; font: 500 clamp(31px, 4vw, 46px)/1.2 var(--serif); }
.research-detail > div:last-child > p:not(.eyebrow) { max-width: 700px; color: var(--muted); }
.tag-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 22px; }
.tag-row span { padding: 7px 10px; border: 1px solid var(--line); color: var(--muted); font-size: 10px; }
.people-section { padding: 78px 0 120px; }
.person-feature { position: relative; margin-bottom: 88px; padding: 30px; display: grid; grid-template-columns: 100px 1fr auto; gap: 24px; align-items: center; background: #151f1b; }
.person-initial { width: 82px; height: 82px; display: grid; place-items: center; border-radius: 50%; color: #fff; background: var(--deep); font: 20px var(--serif); }
.person-feature h2 { margin: 0; font: 500 30px var(--serif); }
.person-feature p { margin: 5px 0; color: var(--muted); font-size: 12px; }
.person-feature .text-link { font-size: 11px; }
.person-more { align-self: end; font-size: 11px; }
.people-heading { margin-bottom: 26px; }
.small-note, .people-footnote { color: var(--muted); font-size: 10px; }
.people-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.person-card { min-height: 173px; padding: 22px; border: 1px solid var(--line); }
.person-photo { width: 100%; height: 220px; margin-bottom: 16px; display: block; object-fit: cover; object-position: center 25%; background: #27322d; }
.person-degree { color: var(--accent); font-size: 9px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
.person-card h3 { margin: 12px 0 8px; font: 500 22px var(--serif); }
.person-card p { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.7; }
.person-card a { color: var(--accent); font-size: 10px; }
.alumni-section { margin-top: 90px; }
.alumni-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; }
.alumni-card { padding: 14px; border: 1px solid var(--line); }
.alumni-photo { width: 100%; height: 190px; display: block; object-fit: cover; object-position: center 20%; background: #27322d; }
.alumni-card h3 { margin: 12px 0 4px; font: 500 18px var(--serif); }
.alumni-card p { margin: 0; color: var(--muted); font-size: 10px; }
.people-footnote { margin: 24px 0 0; }
.publication-list { padding: 74px 0 120px; }
.conference-year { margin-top: 56px; }
.conference-list, .patent-list { margin: 0; padding: 0; list-style: none; }
.conference-list li, .patent-list li { padding: 18px 0; border-top: 1px solid var(--line); }
.conference-list li { font-size: 13px; line-height: 1.8; }
.patent-list { margin-bottom: 60px; }
.patent-list li:last-child { border-bottom: 1px solid var(--line); }
.patent-status { color: var(--accent); font-size: 10px; font-weight: 750; letter-spacing: .08em; }
.patent-list p { margin: 8px 0 0; font-size: 13px; }
.patent-previous { margin-top: 72px; }
.publication-year-group { display: grid; grid-template-columns: 120px 1fr; column-gap: 28px; margin-bottom: 60px; }
.publication-year-group > h2 { grid-column: 1; grid-row: 1; margin: 0; color: var(--accent); font: 500 30px var(--serif); }
.publication-year-group > article { grid-column: 2; }
.publication-full { padding: 22px 0 25px; border-top: 1px solid var(--line); }
.pub-type { color: var(--accent); font-size: 9px; font-weight: 750; letter-spacing: .13em; }
.publication-full h3 { margin: 8px 0; font: 500 20px/1.4 var(--serif); }
.publication-full p { margin: 0 0 8px; color: var(--muted); font-size: 11px; }
.publication-full a { font-size: 10px; font-weight: 700; }
.news-list { padding: 76px 0 120px; }
.news-year { display: grid; grid-template-columns: 120px 1fr; column-gap: 28px; }
.news-year > h2 { grid-column: 1; grid-row: 1; margin: 0; color: var(--accent); font: 500 30px var(--serif); }
.news-year > .news-row { grid-column: 2; }
.news-row { padding: 20px 0 22px; display: grid; grid-template-columns: 110px 1fr; gap: 20px; border-top: 1px solid var(--line); }
.news-row time { color: var(--muted); font-size: 10px; }
.news-category { color: var(--accent); font-size: 9px; font-weight: 750; letter-spacing: .12em; }
.news-row h3 { margin: 6px 0 0; font-size: 14px; font-weight: 600; }
.lecture-section { padding: 80px 0 120px; }
.lecture-detail-list { padding: 56px 0 120px; }
.lecture-source-note { margin: 22px 0 42px; color: var(--muted); font-size: 12px; }
.lecture-detail { padding: 38px 0 44px; border-top: 1px solid var(--line); scroll-margin-top: 24px; }
.lecture-detail h2 { margin: 0 0 15px; font: 500 clamp(28px, 3.3vw, 40px)/1.25 var(--serif); }
.lecture-detail h2 span { display: block; margin-top: 5px; color: var(--muted); font-size: .55em; font-weight: 400; letter-spacing: 0; }
.lecture-detail > p:not(.eyebrow) { max-width: 760px; color: var(--muted); font-size: 13px; }
.lecture-detail h3 { margin: 28px 0 8px; color: var(--accent); font-size: 12px; letter-spacing: .08em; }
.lecture-resource-list { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--line); }
.lecture-resource-list li { padding: 12px 14px; display: flex; justify-content: space-between; gap: 20px; border-bottom: 1px solid var(--line); font-size: 12px; }
.lecture-resource-list li > span:last-child { color: var(--muted); text-align: right; }
.lecture-resource-list a { font-weight: 600; }
.lecture-contact a { color: var(--accent); }
.semester-grid { margin-top: 26px; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.semester-item { min-height: 130px; padding: 19px; display: flex; flex-direction: column; justify-content: space-between; border: 1px solid var(--line); }
.semester-item span { color: var(--muted); font: 16px var(--serif); }
.semester-item strong { font-size: 12px; letter-spacing: .12em; }
.semester-current { color: #fff; background: var(--deep); border-color: var(--deep); }
.semester-current span { color: #d2c2a8; }
.lecture-section .people-footnote { margin-top: 24px; }
.lecture-archive { margin-top: 72px; }
.lecture-year { margin: 0 0 32px; display: grid; grid-template-columns: minmax(120px, .35fr) minmax(0, 1.65fr); gap: 32px; }
.lecture-year h2 { margin: 0; color: var(--accent); font-size: 24px; font-weight: 700; }
.lecture-semester { padding: 0 0 32px; border-bottom: 1px solid var(--line); }
.lecture-semester + .lecture-semester { padding-top: 28px; }
.lecture-semester h3 { margin: 0 0 16px; color: var(--ink); font-size: 15px; font-weight: 700; letter-spacing: .08em; }
.lecture-course-list { margin: 0; padding: 0; list-style: none; }
.lecture-course { padding: 15px 0; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 20px; align-items: center; border-top: 1px solid var(--line); }
.lecture-course h4 { margin: 0; font-size: 14px; font-weight: 600; }
.lecture-course p { margin: 5px 0 0; color: var(--muted); font-size: 11px; }
.lecture-course-link { flex: 0 0 auto; color: var(--accent); font-size: 11px; font-weight: 700; }
.lecture-course-link:hover { color: var(--ink); }
.lecture-materials { margin-top: 52px; padding: 24px; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 24px; align-items: center; border: 1px solid var(--line); background: #151f1b; }
.lecture-materials h3 { margin: 0 0 8px; font-size: 16px; }
.lecture-materials p { max-width: 680px; margin: 0; color: var(--muted); font-size: 12px; }
.contact-layout { padding: 90px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 10vw; }
.contact-primary h2 { font-size: clamp(38px, 5vw, 62px); }
.contact-primary > p:not(.eyebrow) { margin: 22px 0; color: var(--muted); font-size: 13px; }
.contact-details { display: flex; flex-direction: column; justify-content: center; gap: 25px; }
.contact-details > div { padding-bottom: 20px; border-bottom: 1px solid var(--line); }
.contact-details span { color: var(--accent); font-size: 9px; font-weight: 750; letter-spacing: .15em; }
.contact-details p { margin: 8px 0 0; font-size: 12px; line-height: 1.9; }
.map-placeholder { position: relative; min-height: 310px; overflow: hidden; background: #1a2420; }
.map-grid { position: absolute; inset: -20%; opacity: .5; background-image: linear-gradient(30deg, transparent 47%, #3b4a43 48%, #3b4a43 49%, transparent 50%), linear-gradient(120deg, transparent 47%, #3b4a43 48%, #3b4a43 49%, transparent 50%), linear-gradient(90deg, transparent 49%, #293832 50%, transparent 51%); background-size: 120px 105px, 160px 125px, 88px 88px; transform: rotate(-8deg); }
.map-label { position: absolute; top: 50%; left: 50%; min-width: 265px; padding: 20px 22px; background: rgba(18,27,23,.96); box-shadow: 0 8px 25px rgba(0,0,0,.24); transform: translate(-50%, -50%); }
.map-pin { color: var(--accent); }
.map-label p { display: inline-block; margin: 0 0 12px 10px; color: var(--muted); font-size: 9px; line-height: 1.6; letter-spacing: .08em; }
.map-label strong { color: var(--ink); font-size: 12px; }
.map-label a { display: block; font-size: 10px; font-weight: 700; }
.research-gallery { margin-top: 38px; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.research-visual { width: 100%; margin: 0; overflow: hidden; border: 1px solid var(--line); background: #101b20; }
.research-visual:first-child { grid-column: 1 / -1; }
.research-visual svg { width: 100%; height: auto; display: block; transition: transform 180ms ease-out; }
.research-visual:hover svg { transform: scale(1.015); }
.pi-profile { margin-bottom: 88px; padding: 30px; display: grid; grid-template-columns: minmax(200px, .55fr) minmax(0, 1.45fr); gap: 34px; background: #151f1b; }
.pi-profile .profile-photo { width: 100%; max-width: 310px; }
.pi-profile .profile-facts { grid-template-columns: 1fr 1.4fr; }
.research-visual figcaption { padding: 12px 18px; color: var(--muted); font-size: 11px; letter-spacing: .03em; }
.original-note { color: var(--muted); font-size: 10px; }
.award-link { display: inline-block; margin-top: 7px; color: var(--accent); font-size: 11px; }
.research-visual figcaption { padding: 13px 16px; color: var(--muted); background: #101b20; font-size: 13px; }

.brand-mark { width: auto; height: auto; border-radius: 0; color: transparent; background: linear-gradient(90deg, #ed3d3d 0 34%, #159c58 34% 67%, #2467d6 67%); background-clip: text; -webkit-background-clip: text; -webkit-text-fill-color: transparent; font-size: 25px; font-weight: 800; letter-spacing: -.08em; }
.brand-name { font-size: 15px; }
.site-nav { gap: clamp(10px, 1.35vw, 18px); }
.site-nav a { font-size: 12px; }
.eyebrow { font-size: 11px; }
.hero h1 .lab-red { color: #ff5151; }
.hero h1 .lab-green { color: #28c477; }
