1	const menuButton = document.querySelector(".menu-toggle");
2	const navigation = document.querySelector(".site-nav");
3	
4	if (menuButton && navigation) {
5	  const closeMenu = () => {
6	    menuButton.setAttribute("aria-expanded", "false");
7	    navigation.classList.remove("is-open");
8	  };
9	
10	  menuButton.addEventListener("click", () => {
11	    const expanded = menuButton.getAttribute("aria-expanded") === "true";
12	    menuButton.setAttribute("aria-expanded", String(!expanded));
13	    navigation.classList.toggle("is-open", !expanded);
14	  });
15	
16	  navigation.addEventListener("click", (event) => {
17	    if (event.target instanceof Element && event.target.closest("a")) closeMenu();
18	  });
19	
20	  document.addEventListener("keydown", (event) => {
21	    if (event.key === "Escape") closeMenu();
22	  });
23	}
24	
25	const journalImpactFactors = new Map([
26	  ["Energy Conversion and Management", "11.8"],
27	  ["International Journal of Heat and Mass Transfer", "6.6"],
28	  ["Scientific Reports", "3.9"],
29	  ["Advanced Materials Interfaces", "4.5"],
30	  ["Membranes", "4.2"],
31	  ["Micromachines", "3.5"],
32	  ["International Journal of Energy Research", "4.2"],
33	  ["Applied Physics B", "2.5"],
34	  ["International Journal of Hydrogen Energy", "9.2"],
35	  ["Solar Energy Materials & Solar Cells", "6.6"],
36	  ["Applied Energy", "12.2"],
37	  ["Renewable Energy", "9.1"],
38	  ["Journal of Thermophysics and Heat Transfer", null],
39	  ["Journal of Quantitative Spectroscopy & Radiative Transfer", "2.0"]
40	]);
41	
42	document.querySelectorAll(".publication-full").forEach((publication) => {
43	  const type = publication.querySelector(".pub-type")?.textContent.trim();
44	  if (type !== "JOURNAL ARTICLE" && type !== "SCOPUS JOURNAL") return;
45	
46	  const journal = publication.querySelector("p em")?.textContent.trim();
47	  if (!journal) return;
48	
49	  const metrics = document.createElement("p");
50	  metrics.className = "journal-metrics";
51	
52	  if (type === "SCOPUS JOURNAL") {
53	    metrics.textContent = "JCR 미등재 · JIF 미부여";
54	  } else {
55	    const impactFactor = journalImpactFactors.get(journal);
56	    metrics.textContent = impactFactor
57	      ? `JCR 2026 · JIF ${impactFactor}`
58	      : "JCR 등재 · JIF 확인 필요";
59	  }
60	
61	  publication.append(metrics);
62	});
