public static class Img {
  public static Bitmap Resize(Bitmap src, int w, int h) {
    var b = new Bitmap(w, h, PixelFormat.Format32bppArgb);
    using (var g = Graphics.FromImage(b)) { g.InterpolationMode = InterpolationMode.HighQualityBicubic; g.SmoothingMode = SmoothingMode.HighQuality; g.PixelOffsetMode = PixelOffsetMode.HighQuality; g.Clear(Color.Transparent); g.DrawImage(src, 0, 0, w, h); }
    return b;
  }
  public static Bitmap SquarePad(Bitmap src, int size, double fill) {
    var b = new Bitmap(size, size, PixelFormat.Format32bppArgb);
    double s = size * fill / Math.Max(src.Width, src.Height);
    int w = (int)(src.Width * s), h = (int)(src.Height * s);
    using (var g = Graphics.FromImage(b)) { g.InterpolationMode = InterpolationMode.HighQualityBicubic; g.SmoothingMode = SmoothingMode.HighQuality; g.PixelOffsetMode = PixelOffsetMode.HighQuality; g.Clear(Color.Transparent); g.DrawImage(src, (size - w) / 2, (size - h) / 2, w, h); }
    return b;
  }
  // recolor blue-dominant pixels to a lighter blue, and green-dominant to a lighter green, keeping alpha
  public static void Recolor(Bitmap b) {
    var r = new Rectangle(0, 0, b.Width, b.Height);
    var d = b.LockBits(r, ImageLockMode.ReadWrite, PixelFormat.Format32bppArgb);
    int n = d.Stride * d.Height; var px = new byte[n]; Marshal.Copy(d.Scan0, px, 0, n);
    for (int i = 0; i < n; i += 4) {
      byte B = px[i], G = px[i+1], R = px[i+2], A = px[i+3];
      if (A == 0) continue;
      if (B > R + 40 && B > G + 30) { px[i] = 0xFF; px[i+1] = 0x9A; px[i+2] = 0x5E; }      // #5E9AFF
      else if (G > R + 40 && G > B + 20) { px[i] = 0x62; px[i+1] = 0xB5; px[i+2] = 0x1E; } // #1EB562
    }
    Marshal.Copy(px, 0, d.Scan0, n); b.UnlockBits(d);
  }
}
"@
$logo = New-Object System.Drawing.Bitmap($logoPath)
$small = [Img]::Resize($logo, 1600, [int](1600 * $logo.Height / $logo.Width))
[Img]::Recolor($small)
$small.Save("$dir\assets\tes-lab-logo-dark.png", [System.Drawing.Imaging.ImageFormat]::Png)
$fav = New-Object System.Drawing.Bitmap("$dir\파비콘_로고_S.png")
foreach ($s in 32, 64, 180, 192, 512) { $o = [Img]::SquarePad($fav, $s, 0.96); $o.Save("$dir\assets\favicon-$s.png", [System.Drawing.Imaging.ImageFormat]::Png); $o.Dispose() }
$seal = New-Object System.Drawing.Bitmap("$dir\assets\knu-seal.png")
"seal corner: $($seal.GetPixel(1,1))  center-edge: $($seal.GetPixel(248,10))"
$o = [Img]::SquarePad($seal, 128, 1.0); $o.Save("$dir\assets\knu-seal-128.png", [System.Drawing.Imaging.ImageFormat]::Png)
Get-ChildItem "$dir\assets" -Filter *.png | Select Name, Length

