param($dir)
$enc = New-Object Text.UTF8Encoding $false
$oldBrand = '<span class="brand-mark">TES</span><span class="brand-name">Thermal Energy<br>Solutions Lab.</span>'
$newBrand = '<img class="brand-mark" src="assets/knu-seal-128.png" alt="Kongju National University" width="46" height="46"><span class="brand-name">TES Lab.<small>Thermal Energy Solutions Lab.</small></span>'
$icons = '<link rel="icon" type="image/png" sizes="32x32" href="assets/favicon-32.png"><link rel="icon" type="image/png" sizes="192x192" href="assets/favicon-192.png"><link rel="apple-touch-icon" href="assets/favicon-180.png">'
$nav = [ordered]@{ "index.html"="Home"; "about.html"="About"; "research.html"="Research"; "team.html"="People"; "publications.html"="Publications"; "open-courses.html"="Open Courses"; "news.html"="News"; "lectures.html"="Lectures"; "contact.html"="Contact" }
$current = @{ "conferences.html"="research.html"; "patents.html"="research.html"; "lecture-archive.html"="lectures.html" }
$sub = [ordered]@{ "research.html"="Research Areas"; "publications.html"="Publications"; "conferences.html"="Conferences"; "patents.html"="Patents"; "open-courses.html"="Open Courses" }

Get-ChildItem $dir -Filter *.html | ForEach-Object {
  $name = $_.Name
  $t = [IO.File]::ReadAllText($_.FullName, [Text.Encoding]::UTF8)
  $t = $t.Replace($oldBrand, $newBrand)
  if ($t -notmatch 'rel="icon"') { $t = $t.Replace('<link rel="stylesheet" href="styles.css">', '<link rel="stylesheet" href="styles.css">' + $icons) }
  $cur = if ($current.ContainsKey($name)) { $current[$name] } else { $name }
  $links = ($nav.Keys | ForEach-Object { if ($_ -eq $cur) { "<a aria-current=`"page`" href=`"$_`">$($nav[$_])</a>" } else { "<a href=`"$_`">$($nav[$_])</a>" } }) -join ''
  $t = [regex]::Replace($t, '<nav id="site-nav"[\s\S]*?</nav>', '<nav id="site-nav" class="site-nav" aria-label="Main menu">' + $links + '</nav>')
  if ($sub.Contains($name) -and $t -notmatch 'class="sub-nav"') {
    $sl = ($sub.Keys | ForEach-Object { if ($_ -eq $name) { "<a aria-current=`"page`" href=`"$_`">$($sub[$_])</a>" } else { "<a href=`"$_`">$($sub[$_])</a>" } }) -join ''
    $subHtml = '<nav class="sub-nav" aria-label="Research menu"><div class="section-wrap">' + $sl + '</div></nav>'
    $idx = $t.IndexOf('</h1></section>')
    if ($idx -ge 0) { $p = $idx + '</h1></section>'.Length; $t = $t.Substring(0, $p) + "`n    " + $subHtml + $t.Substring($p) }
  }
  [IO.File]::WriteAllText($_.FullName, $t, $enc)
  "$name brand=$(([regex]::Matches($t,'knu-seal-128')).Count) icon=$($t -match 'favicon-32') sub=$($t -match 'sub-nav')"
}

