/* ===================== 2026-11 refresh ===================== */
:root { --ink: #eef2ee; --muted: #b3c0b9; }
body { font-size: 17px; line-height: 1.75; }

/* header: school seal + sticky */
.site-header { position: sticky; top: 0; z-index: 40; height: 84px; background: rgba(16, 23, 20, .93); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
.brand { gap: 14px; }
.brand-mark { width: 46px; height: 46px; display: block; flex: 0 0 auto; border-radius: 50%; background: #fff; object-fit: cover; font-size: 0; letter-spacing: 0; -webkit-text-fill-color: initial; box-shadow: 0 0 0 2px rgba(255, 255, 255, .08); }
.brand-name { display: flex; flex-direction: column; font-size: 21px; font-weight: 800; letter-spacing: -.01em; line-height: 1.1; }
.brand-name small { margin-top: 4px; color: var(--muted); font-size: 12.5px; font-weight: 500; letter-spacing: .02em; }
.site-nav { gap: clamp(14px, 1.6vw, 26px); }
.site-nav a { font-size: 15.5px; font-weight: 600; }
.sub-nav { position: sticky; top: 84px; z-index: 30; border-bottom: 1px solid var(--line); background: rgba(21, 31, 27, .95); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); }
.sub-nav .section-wrap { display: flex; gap: 8px; padding: 12px 0; overflow-x: auto; scrollbar-width: none; }
.sub-nav a { flex: 0 0 auto; padding: 7px 16px; border: 1px solid var(--line); border-radius: 999px; color: var(--muted); font-size: 15px; font-weight: 600; white-space: nowrap; }
.sub-nav a:hover { color: var(--ink); border-color: var(--accent); }
.sub-nav a[aria-current="page"] { color: #17201c; background: var(--accent); border-color: var(--accent); }
.research-detail, .lecture-detail { scroll-margin-top: 160px; }

/* home hero: logo sits directly on the page background */
.hero-logo-panel { padding: 0; border: 0; border-radius: 0; background: transparent; box-shadow: none; }
.hero-logo-panel img { filter: drop-shadow(0 12px 32px rgba(0, 0, 0, .35)); }
.recruit-badge { display: inline-flex; align-items: center; gap: 10px; margin-bottom: 26px; padding: 8px 16px; border: 1px solid rgba(47, 199, 122, .45); border-radius: 999px; color: #bff0d4; background: rgba(47, 199, 122, .08); font-size: 15px; font-weight: 600; }
.recruit-badge:hover { color: #fff; border-color: #2fc77a; }
.recruit-dot { width: 8px; height: 8px; border-radius: 50%; background: #2fc77a; animation: recruit-pulse 2s infinite; }
@keyframes recruit-pulse { 0% { box-shadow: 0 0 0 0 rgba(47, 199, 122, .55); } 70% { box-shadow: 0 0 0 10px rgba(47, 199, 122, 0); } 100% { box-shadow: 0 0 0 0 rgba(47, 199, 122, 0); } }
@media (prefers-reduced-motion: reduce) { .recruit-dot { animation: none; } .research-card, .person-card, .research-visual img { transition: none; } }

/* home research cards with thumbnails */
.research-card { min-height: 0; padding: 0 0 26px; justify-content: flex-start; gap: 14px; transition: transform .2s ease, background-color .2s ease; }
.research-card::after { display: none; }
.research-thumb { width: 100%; aspect-ratio: 16 / 9; display: block; object-fit: cover; border-bottom: 1px solid rgba(255, 255, 255, .08); }
.research-card .card-no, .research-card h3, .research-card .card-arrow { margin: 0 26px; }
.research-card .card-no { margin-top: 8px; }
.research-card:hover { transform: translateY(-4px); }

/* research page */
.research-lead { max-width: 860px; margin: 0 0 64px; }
.research-lead p { margin: 0 0 14px; color: var(--muted); font-size: 19px; line-height: 1.85; }
.research-jump { margin: 30px 0 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; list-style: none; }
.research-jump a { height: 100%; padding: 18px 20px; display: flex; flex-direction: column; gap: 6px; border: 1px solid var(--line); background: #151f1b; font-size: 16.5px; font-weight: 600; line-height: 1.45; }
.research-jump a span { color: var(--accent); font-size: 14px; letter-spacing: .12em; }
.research-jump a:hover { color: var(--ink); border-color: var(--accent); }
.research-detail { padding: 52px 0 72px; grid-template-columns: minmax(60px, .22fr) minmax(0, 1.78fr); }
.research-detail h2 { font-size: clamp(32px, 3.6vw, 46px); }
.research-detail > div:last-child > p:not(.eyebrow) { max-width: 820px; font-size: 18px; line-height: 1.85; }
.tag-row span { padding: 8px 13px; border-radius: 999px; color: #cdd8d2; font-size: 14.5px; }
.research-gallery { margin-top: 40px; grid-template-columns: 1fr; gap: 26px; }
.research-visual { border-radius: 14px; background: #0f1a17; }
.research-visual a { display: block; overflow: hidden; }
.research-visual img { width: 100%; height: auto; display: block; transition: transform .25s ease; }
.research-visual:hover img { transform: scale(1.01); }
.research-visual figcaption { padding: 14px 20px; border-top: 1px solid var(--line); color: var(--muted); background: #0f1a17; font-size: 16px; }

/* people: grouped, uncropped photos */
.people-group-title { margin: 56px 0 20px; display: flex; align-items: center; gap: 16px; color: var(--accent); font-size: 15px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.people-group-title::after { flex: 1; height: 1px; background: var(--line); content: ""; }
.people-heading + .people-group-title { margin-top: 10px; }
.people-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 18px; }
.person-card { min-height: 0; padding: 16px 16px 22px; display: flex; flex-direction: column; border-radius: 12px; background: #131c18; transition: border-color .2s ease, transform .2s ease; }
.person-card:hover { border-color: #4b5d55; transform: translateY(-3px); }
.photo-frame { margin-bottom: 16px; aspect-ratio: 3 / 4; display: flex; align-items: center; justify-content: center; overflow: hidden; border-radius: 8px; background: #1c2723; }
.person-photo, .alumni-photo { width: 100%; height: 100%; margin: 0; object-fit: contain; object-position: center; background: transparent; }
.person-card h3 { margin: 6px 0 10px; font-size: 23px; }
.interest-chips { margin: 0 0 14px; padding: 0; display: flex; flex-wrap: wrap; gap: 6px; list-style: none; }
.interest-chips li { padding: 4px 10px; border-radius: 999px; color: #e9c3ae; background: rgba(217, 139, 101, .12); font-size: 13.5px; line-height: 1.5; }
.person-card .person-email { margin-top: auto; color: var(--muted); font-size: 13.5px; word-break: break-all; }
.person-card .person-email:hover { color: var(--accent); }
.alumni-grid { gap: 16px; }
.alumni-card { padding: 14px 14px 18px; border-radius: 12px; background: #131c18; }
.alumni-card .photo-frame { margin-bottom: 12px; }
.alumni-card h3 { font-size: 19px; }
.alumni-card p { font-size: 14px; }

/* open courses */
.open-course-section { padding: 70px 0 120px; }
.course-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
.course-card { --area: var(--accent); position: relative; padding: 28px 28px 26px; display: flex; flex-direction: column; gap: 8px; overflow: hidden; border: 1px solid var(--line); border-radius: 14px; background: #131c18; }
.course-card::before { position: absolute; top: 0; bottom: 0; left: 0; width: 4px; background: var(--area); content: ""; }
.course-card[data-area="thermography"] { --area: #ff7a5c; }
.course-card[data-area="thermal"] { --area: #5e9aff; }
.course-card[data-area="energy"] { --area: #2fc77a; }
.course-card[data-area="multiphysics"] { --area: #ffd166; }
.course-area { align-self: flex-start; padding: 4px 12px; border: 1px solid var(--area); border-radius: 999px; color: var(--area); font-size: 13px; font-weight: 700; letter-spacing: .04em; }
.course-series { margin: 10px 0 0; color: var(--muted); font-size: 14px; font-weight: 600; letter-spacing: .06em; }
.course-card h2 { margin: 0; font-size: 23px; font-weight: 650; line-height: 1.45; letter-spacing: -.01em; }
.course-title-en { margin: 0; color: var(--muted); font-size: 16px; }
.course-speaker { margin: 12px 0 0; padding-top: 14px; border-top: 1px solid var(--line); font-size: 16px; font-weight: 600; }
