param($file)
$enc = New-Object Text.UTF8Encoding $false
$t = [IO.File]::ReadAllText($file, [Text.Encoding]::UTF8)
$seen = @{}
$t = [regex]::Replace($t, '<time datetime="([0-9-]+)">([\s\S]*?)<div class="news-art">', {
  param($m)
  $d = $m.Groups[1].Value
  if ($seen.ContainsKey($d)) { $seen[$d]++ } else { $seen[$d] = 0 }
  $name = "news-$d"
  if ($seen[$d] -gt 0) { $name += "-" + [char](97 + $seen[$d]) }
  '<time datetime="' + $d + '">' + $m.Groups[2].Value + '<div class="news-art" data-photo="assets/news/' + $name + '">'
})
# first duplicate gets "-a" suffix
